package service
import("context";"crypto/sha1";"crypto/sha256";"crypto/sha512";"encoding/base64";"encoding/hex";"fmt";"hash";"io";"os";"path/filepath";"strings";"sync";"github.com/ynw0/airgap-mirror/internal/domain";"github.com/ynw0/airgap-mirror/internal/pack";"github.com/ynw0/airgap-mirror/internal/ports")
type Downloader struct{Plans ports.PlanStore;Exec ports.TransferExecutionStore;Progress ports.DownloadProgressStore;Fetcher ports.ArtifactFetcher;Concurrency int;ProgressEvery int64};func(d Downloader)DownloadBatch(ctx context.Context,bid,out string)error{ps,e:=d.Exec.ListPacks(ctx,bid);if e!=nil{return e};n:=d.Concurrency;if n<=0{n=4};jobs:=make(chan domain.Pack);errs:=make(chan error,1);ctx,cancel:=context.WithCancel(ctx);defer cancel();var wg sync.WaitGroup;for i:=0;i<n;i++{wg.Add(1);go func(){defer wg.Done();for p:=range jobs{if x:=d.downloadPack(ctx,p,out);x!=nil{select{case errs<-x:cancel();default:};return}}}()};for _,p:=range ps{select{case jobs<-p:case<-ctx.Done():break}};close(jobs);wg.Wait();select{case x:=<-errs:return x;default:if ctx.Err()!=nil{return ctx.Err()};return nil}}
func(d Downloader)downloadPack(ctx context.Context,p domain.Pack,out string)error{dir:=filepath.Join(out,"packs");if e:=os.MkdirAll(dir,0755);e!=nil{return e};pth:=filepath.Join(dir,fmt.Sprintf("%06d.agp",p.Sequence));h:=domain.PackHeader{PackID:p.ID,EpochID:p.EpochID,BatchID:p.BatchID};var w *pack.Writer;var e error;if _,x:=os.Stat(pth);x==nil{w,e=pack.Resume(pth,h)}else{w,e=pack.Create(pth,h)};if e!=nil{return e};e=d.Exec.WalkPackArtifacts(ctx,p.ID,func(a domain.Artifact)error{st,x:=d.Progress.EntryState(ctx,a.ID);if x!=nil&&x!=domain.ErrNotFound{return x};if st.Status==domain.DownloadVerified{return nil};tmp:=pth+"."+a.ID+".part";sha,size,x:=d.downloadArtifact(ctx,a,tmp,st);if x!=nil{return x};if x=d.Plans.FinalizeArtifact(ctx,a.ID,size,sha);x!=nil{return x};a.SHA256=sha;f,x:=os.Open(tmp);if x!=nil{return x};loc,x:=w.Append(ctx,domain.PackEntry{Artifact:a},f);f.Close();if x!=nil{return x};if x=d.Plans.SetArtifactPackLocation(ctx,a.ID,loc);x!=nil{return x};if x=os.Remove(tmp);x!=nil{return x};return d.Progress.MarkEntryState(ctx,domain.DownloadEntryProgress{EntryID:a.ID,Status:domain.DownloadVerified,Downloaded:size})});if e!=nil{w.Close();return e};if e=w.Close();e!=nil{return e};sha,size,e:=pack.FileSHA256(pth);if e!=nil{return e};p.FilePath=pth;p.Size=size;p.SHA256=sha;p.Status=domain.PackReady;return d.Exec.UpdatePack(ctx,p)}
func(d Downloader)downloadArtifact(ctx context.Context,a domain.Artifact,tmp string,st domain.DownloadEntryProgress)(string,int64,error){var off int64;if f,e:=os.Stat(tmp);e==nil{off=f.Size()};if st.Downloaded!=0&&st.Downloaded!=off{return "",0,fmt.Errorf("download offset mismatch")};f,e:=os.OpenFile(tmp,os.O_CREATE|os.O_WRONLY|os.O_APPEND,0644);if e!=nil{return "",0,e};defer f.Close();r,e:=d.Fetcher.Open(ctx,ports.FetchRequest{URL:a.UpstreamURL,Offset:off,ETag:st.ETag,LastModified:st.LastModified});if e!=nil{return "",0,e};defer r.Body.Close();if r.StatusCode<200||r.StatusCode>=300{return "",0,fmt.Errorf("http %d",r.StatusCode)};buf:=make([]byte,4<<20);written:=off;step:=d.ProgressEvery;if step<=0{step=64<<20};next:=written+step;for{n,x:=r.Body.Read(buf);if n>0{if _,e=f.Write(buf[:n]);e!=nil{return "",written,e};written+=int64(n);if written>=next{if e=d.Progress.MarkEntryState(ctx,domain.DownloadEntryProgress{EntryID:a.ID,Status:domain.DownloadDownloading,Downloaded:written,ETag:r.ETag,LastModified:r.LastModified});e!=nil{return "",written,e};next=written+step}};if x==io.EOF{break};if x!=nil{return "",written,x}};if a.Size>0&&written!=a.Size{return "",written,fmt.Errorf("size mismatch")};sha,_,e:=verifyFile(tmp,a.UpstreamIntegrity);if e!=nil{return "",written,e};if a.SHA256!=""&&sha!=strings.ToLower(a.SHA256){return "",written,fmt.Errorf("sha256 mismatch")};return sha,written,nil}
func verifyFile(p,integrity string)(string,int64,error){f,e:=os.Open(p);if e!=nil{return "",0,e};defer f.Close();h:=sha256.New();var x hash.Hash;var want []byte;if integrity!=""{alg,val,ok:=strings.Cut(integrity,"-");if !ok{return "",0,fmt.Errorf("invalid integrity")};want,e=base64.StdEncoding.DecodeString(val);if e!=nil{return "",0,e};switch strings.ToLower(alg){case"sha512":x=sha512.New();case"sha256":x=sha256.New();case"sha1":x=sha1.New();default:return "",0,fmt.Errorf("unsupported integrity %s",alg)}};ws:=[]io.Writer{h};if x!=nil{ws=append(ws,x)};n,e:=io.Copy(io.MultiWriter(ws...),f);if e!=nil{return "",n,e};if x!=nil&&!equalBytes(x.Sum(nil),want){return "",n,fmt.Errorf("upstream integrity mismatch")};return hex.EncodeToString(h.Sum(nil)),n,nil};func equalBytes(a,b []byte)bool{if len(a)!=len(b){return false};var x byte;for i:=range a{x|=a[i]^b[i]};return x==0}
